function go(path:string){ history.pushState({},"",path); window.dispatchEvent(new PopStateEvent("popstate")); window.scrollTo({top:0,behavior:"smooth"}); }
function Link({to,children,className=""}:{to:string;children:ReactNode;className?:string}){return <a className={className} href={to} onClick={e=>{if(!e.ctrlKey&&!e.metaKey){e.preventDefault();go(to)}}}>{children}</a>}
function Icon({children}:{children:string}){return <span className="ns-icon" aria-hidden="true">{children}</span>}

function Header(){const [open,setOpen]=useState(false);const [lang,setHeaderLang]=useState<"en"|"zh">(()=>localStorage.getItem("chinadg-lang")==="zh"?"zh":"en");const switchLang=()=>{const next=lang==="en"?"zh":"en";localStorage.setItem("chinadg-lang",next);setHeaderLang(next);location.reload()};return <header className="ns-header"><div className="ns-shell ns-header-in"><Link to="/" className="ns-brand"><BrandLogo subtitle={lang==="zh"?"独立化工品寻源与出口协调服务":"Independent Chemical Sourcing & Export Coordinator"}/></Link><nav className={open?"open":""}>{nav.map(([en,zh,path])=><Link key={path} to={path} className={location.pathname===path?"active":""}>{lang==="zh"?zh:en}</Link>)}</nav><div className="ns-header-actions"><button className="ns-lang" onClick={switchLang}>◉ {lang==="en"?"EN | 中文":"中文 | EN"}</button><Link to="/contact" className="ns-btn ns-btn-small">{lang==="zh"?"沟通采购需求":"Discuss Your Requirement"} →</Link><button className="ns-menu" onClick={()=>setOpen(!open)} aria-label="Menu">☰</button></div></div></header>}
function Footer(){const lang=localStorage.getItem("chinadg-lang")==="zh"?"zh":"en";return <footer className="ns-footer"><div className="ns-shell"><div className="ns-footer-top"><div className="ns-brand light"><b>ChinaChemExport</b><small>{lang==="zh"?"独立化工品寻源与出口协调服务":"Independent Chemical Sourcing & Export Coordinator"}</small></div><div className="ns-footer-links">{nav.slice(0,8).map(([en,zh,p])=><Link key={p} to={p}>{lang==="zh"?zh:en}</Link>)}</div></div><div className="ns-footer-bottom"><p>{lang==="zh"?"ChinaChemExport 是独立运营的寻源与协调服务网站。生产商、签约出口主体及持证操作服务方均按具体交易确认。":"ChinaChemExport is an independently operated sourcing and coordination service. Manufacturer, contracting exporter and licensed operating parties are confirmed for each transaction."}</p><span>© 2026 ChinaChemExport</span></div></div></footer>}
function Layout({children}:{children:ReactNode}){return <><Header/>{children}<Footer/></>}
function Button({to,children,secondary=false}:{to:string;children:ReactNode;secondary?:boolean}){return <Link to={to} className={`ns-btn ${secondary?"ns-btn-secondary":""}`}>{children} →</Link>}
function SectionTitle({eyebrow,title,text,action}:{eyebrow?:string;title:string;text?:string;action?:ReactNode}){return <div className="ns-section-head"><div>{eyebrow&&<small>{eyebrow}</small>}<h2>{title}</h2>{text&&<p>{text}</p>}</div>{action}</div>}
