function HeroFlow({kind,lang="en"}:{kind:keyof typeof heroFlows;lang?:"en"|"zh"}){const labels=heroFlows[kind][lang];const heading={products:{en:"Supply option review",zh:"供应方案核验"},insights:{en:"How practical guidance is built",zh:"实务指南如何形成"},contact:{en:"What happens after your message",zh:"发送需求后的处理流程"}}[kind][lang];return <div className={`ns-business-flow ${kind}`} aria-label={heading}><div className="ns-business-flow-head"><span>{heading}</span><b>01—04</b></div><div className="ns-business-flow-track">{labels.map((label,index)=><article key={label}><i>{String(index+1).padStart(2,"0")}</i><span>{label}</span>{index<labels.length-1&&<b aria-hidden="true">→</b>}</article>)}</div><p>{kind==="insights"?(lang==="zh"?"公开资料 × 实际业务经验 × 买家视角":"Public sources × field experience × buyer perspective"):(lang==="zh"?"每一步均围绕具体询盘确认":"Confirmed around the specific inquiry at each step")}</p></div>}
function PageHero({eyebrow,title,text,children,visual="products",lang="en"}:{eyebrow?:string;title:string;text:string;children?:ReactNode;visual?:string;lang?:"en"|"zh"}){const photo=visual==="sourcing"?"/page-assets/shandong-sourcing-field-review.png":visual==="export"?"/page-assets/chemical-export-port-review.png":"";const isContact=visual==="contact"||eyebrow?.includes("CONTACT")||eyebrow?.includes("联系");const flowKind=(isContact?"contact":"products") as keyof typeof heroFlows;const flowLang=eyebrow?.includes("化工")||eyebrow?.includes("联系")?"zh":lang;return <section className="ns-page-hero"><div className="ns-shell ns-hero-grid"><div><small>{eyebrow}</small><h1>{title}</h1><p>{text}</p><div className="ns-actions">{children}</div></div>{photo?<div className={`ns-hero-photo ${visual}`}><img src={photo} alt=""/><div><b>{visual==="sourcing"?"Regional supply review":"Shipment preparation review"}</b><span>{visual==="sourcing"?"Product · supplier · specification · packing":"Packing · documents · customs · booking"}</span></div></div>:<HeroFlow kind={flowKind} lang={flowLang}/>}</div></section>}
function CompactPageIntro({eyebrow,title,text,children}:{eyebrow:string;title:string;text:string;children?:ReactNode}){return <section className="ns-page-intro"><div className="ns-shell"><small>{eyebrow}</small><div className="ns-page-intro-row"><div><h1>{title}</h1><p>{text}</p></div><div className="ns-actions">{children}</div></div></div></section>}

