function CoordinatorInquiry({lang="en"}:{lang?:"en"|"zh"}={}){const zh=lang==="zh";return <section className="ns-section ns-contact-band"><div className="ns-shell ns-contact-grid"><article className="ns-profile"><img className="ns-coordinator-photo" src="/page-assets/chao-zhang-portrait.png" alt={zh?"Evan Cole，山东独立化工品寻源与出口协调人":"Evan Cole, independent chemical sourcing and export coordinator in Shandong"}/><div><small>{zh?"您的本地协调联系人":"YOUR LOCAL POINT OF COORDINATION"}</small><h2>{zh?"直接与 Evan 沟通":"Work Directly with Evan"}</h2><strong className="ns-profile-name">Evan Cole · {zh?"独立化工品寻源与出口协调人":"Independent Chemical Sourcing & Export Coordinator"}</strong><p>{zh?"我拥有多年国内危险化学品贸易实务经验，长期接触山东及周边化工品供应渠道，熟悉从寻源、规格和批次资料核验，到包装、危险品单证及国际出运协调的实际要求。":"I have years of hands-on experience in China’s domestic dangerous-chemical trade, established access to Shandong supply channels, and practical familiarity with sourcing, specification review, packing, dangerous-goods documents and international shipment coordination."}</p><div className="ns-profile-tags"><span>{zh?"危化品贸易经验":"DG trade experience"}</span><span>{zh?"区域供应链资源":"Regional supply access"}</span><span>{zh?"熟悉出口流程":"Export process familiarity"}</span></div><div className="ns-actions"><a className="ns-btn whatsapp" href="https://wa.me/8618678695200">{zh?"WhatsApp 沟通":"Chat on WhatsApp"}</a><a className="ns-btn ns-btn-secondary" href="mailto:18678695200@163.com">{zh?"发送邮件":"Email Me"}</a></div></div></article><QuickForm lang={lang}/></div></section>}

function QuickForm({preset="",lang="en"}:{preset?:string;lang?:"en"|"zh"}){const zh=lang==="zh";const [status,setStatus]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setStatus(zh?"正在提交…":"Sending…");const f=new FormData(e.currentTarget);const body=Object.fromEntries(f.entries());try{const r=await fetch("/api/inquiry",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});if(!r.ok)throw new Error();setStatus(zh?"需求已收到，我会审核后直接回复。":"Requirement received. I will review it and reply directly.");e.currentTarget.reset()}catch{setStatus(zh?"暂时无法提交，请使用 WhatsApp 或电子邮件。":"Unable to send right now. Please use WhatsApp or email.")}}return <form className="ns-quick-form" onSubmit={submit}><h2>{zh?"提交您的采购需求":"Send Your Sourcing Requirement"}</h2><div className="ns-form-grid"><label>{zh?"产品":"Product"}<input name="product" defaultValue={preset} required placeholder={zh?"例如：Xylene":"e.g. Xylene"}/></label><label>{zh?"CAS 或规格":"CAS or Specification"}<input name="message" placeholder={zh?"CAS、纯度或牌号":"CAS, purity or grade"}/></label><label>{zh?"数量与包装":"Quantity & Packing"}<input name="quantity" required placeholder={zh?"例如：20 吨，桶装":"e.g. 20 MT, drums"}/></label><label>{zh?"目的港":"Destination Port"}<input name="destination" required placeholder={zh?"例如：新加坡":"e.g. Singapore"}/></label><label>{zh?"电子邮箱":"Email"}<input type="email" name="email" required placeholder="name@company.com"/></label><label>WhatsApp<input name="contact" placeholder={zh?"国家代码 + 电话号码":"Country code + number"}/></label></div><button className="ns-btn" type="submit">{zh?"提交供应与出口审核需求":"Request a Supply & Export Review"} →</button>{status&&<p className="ns-status">{status}</p>}</form>}

function ProductGrid({items,lang="en"}:{items:Product[];lang?:"en"|"zh"}){const zh=lang==="zh";return <div className="ns-product-grid">{items.map(p=><Link to={`/products/${p.slug}`} className="ns-product-card" key={p.slug}><div className="ns-product-img"><img src={p.image} alt={`${p.name} sourcing and export packing`} onError={e=>e.currentTarget.style.display="none"}/></div><h3>{p.name}</h3><small>CAS {p.cas}</small><p>{zh?"供应商、规格、包装及出口条件按具体询盘核验。":p.focus}</p><span>{zh?"查看寻源详情":"View sourcing details"} →</span></Link>)}</div>}

